import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';import {fileURLToPath} from 'node:url';
const music=new URL('../../music/rpg/',import.meta.url),manifest=JSON.parse(fs.readFileSync(new URL('manifest.json',music))),qa=JSON.parse(fs.readFileSync(new URL('audio-qa.json',music)));
test('all deployed orchestral bytes match their manifest and complete-file decoded duration receipt',()=>{assert.equal(manifest.tracks.length,28);for(const t of manifest.tracks){const bytes=fs.readFileSync(new URL(t.audio,music));assert.equal(crypto.createHash('sha256').update(bytes).digest('hex'),t.sha256,t.id);const checked=qa.tracks.find(a=>a.id===t.id);assert.ok(checked,t.id);assert.ok(Math.abs(checked.duration_s-t.duration_s)<.02,t.id);assert.ok(checked.peak<1&&checked.rms>.001,t.id);}assert.ok(qa.tracks.find(t=>t.id==='credits').duration_s>31);});
test('listening room shares current audio assets rather than downloading duplicate embedded tracks',()=>{const html=fs.readFileSync(new URL('listen.html',music),'utf8');assert.ok(!html.includes('data:audio/'));for(const t of manifest.tracks)assert.ok(html.includes('"audio":"'+t.audio+'"'),t.id);});
test('configured static output stays within the hosting expanded-size limit',()=>{const dist=fileURLToPath(new URL('../../../',import.meta.url));function size(p){return fs.readdirSync(p,{withFileTypes:true}).reduce((sum,e)=>{const f=path.join(p,e.name);return sum+(e.isDirectory()?size(f):fs.statSync(f).size);},0);}const bytes=size(dist);assert.ok(bytes<256*1024*1024,bytes+' bytes exceeds the 256 MiB hosting limit');});
